<?php require_login(['admin','teacher']);$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO timetable(class_id,day_name,period_no,subject_id,teacher_id,start_time,end_time) VALUES(?,?,?,?,?,?,?)');$s->execute([(int)$_POST['class_id'],$_POST['day_name'],(int)$_POST['period_no'],(int)$_POST['subject_id'],($_POST['teacher_id']?:null),($_POST['start_time']?:null),($_POST['end_time']?:null)]);flash('success','Timetable entry added.');redirect('index.php?page=timetable');}if(isset($_GET['delete'])&&user()['role']==='admin'){$pdo->prepare('DELETE FROM timetable WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Timetable entry deleted.');redirect('index.php?page=timetable');}$classes=$pdo->query('SELECT * FROM classes ORDER BY class_name,section')->fetchAll();$subjects=$pdo->query('SELECT * FROM subjects ORDER BY subject_name')->fetchAll();$teachers=$pdo->query("SELECT id,name FROM teachers WHERE status='active' ORDER BY name")->fetchAll();$rows=$pdo->query('SELECT t.*,c.class_name,c.section,s.subject_name,te.name teacher FROM timetable t JOIN classes c ON c.id=t.class_id JOIN subjects s ON s.id=t.subject_id LEFT JOIN teachers te ON te.id=t.teacher_id ORDER BY c.class_name,t.day_name,t.period_no')->fetchAll();?><div class="grid2"><section class="panel"><h2>Add Timetable Entry</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Class<select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['class_name'].' - '.$c['section'])?></option><?php endforeach;?></select></label><label>Day<select name="day_name"><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $d):?><option><?=$d?></option><?php endforeach;?></select></label><label>Period No<input type="number" name="period_no" value="1" min="1"></label><label>Subject<select name="subject_id"><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['subject_name'])?></option><?php endforeach;?></select></label><label>Teacher<select name="teacher_id"><option value="">—</option><?php foreach($teachers as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></label><label>Start<input type="time" name="start_time"></label><label>End<input type="time" name="end_time"></label><button class="btn primary wide">Add Entry</button></form></section><section class="panel"><h2>Timetable</h2><div class="table-wrap"><table><thead><tr><th>Class</th><th>Day</th><th>Period</th><th>Subject</th><th>Teacher</th><th>Time</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['class_name'].' '.$r['section'])?></td><td><?=e($r['day_name'])?></td><td><?=e($r['period_no'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['teacher']??'—')?></td><td><?=e(substr((string)$r['start_time'],0,5).'–'.substr((string)$r['end_time'],0,5))?></td><td><?php if(user()['role']==='admin'):?><a class="action danger-text" href="index.php?page=timetable&delete=<?=$r['id']?>">Delete</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div>
